    /* Memory1 */
    // Initialize unit delay: Memory1
    model->states.Memory1_state[0] = 0;
    model->states.Memory1_state[1] = 0;
    model->states.Memory1_state[2] = 0;

    /* Memory2 */
    // Initialize unit delay: Memory2
    model->states.Memory2_state[0] = 0;
    model->states.Memory2_state[1] = 0;
    model->states.Memory2_state[2] = 0;

    /* Memory3 */
    // Initialize unit delay: Memory3
    model->states.Memory3_state = 0;

    /* Memory4 */
    // Initialize unit delay: Memory4
