        model->enable_states.S_IVB_Stage_Ullage_Rocket_Motors_Time_Since_Engine_Start_Timer_Initialization_enabled = (_trig && !model->enable_states.S_IVB_Stage_Ullage_Rocket_Motors_Time_Since_Engine_Start_Timer_Initialization_trig_prev) ? 1 : 0;
