/*
 * Deferred discrete state updates (unit_delay and Memory): state = u
 * Runs once per major step, after RK4 / Euler integration completes.
 * Output phase already published the previous state during evaluate_algebraic.
 */
void saturn_ib_stack_update_memory_states(saturn_ib_stack_t* model) {

    /* Deferred unit_delay / Memory state updates (post-integration) */

    /* Saturn_Instrument_Unit_IU_ST_124M_Stabilized_Platform_Memory state update */
    // Unit Delay state update: Saturn_Instrument_Unit_IU_ST_124M_Stabilized_Platform_Memory
    for (int i = 0; i < 3; i++) {
        model->states.Saturn_Instrument_Unit_IU_ST_124M_Stabilized_Platform_Memory_state[i] = model->signals.Saturn_Instrument_Unit_IU_ST_124M_Stabilized_Platform_Fine_Resolver_Quantization[i];
    }

    /* Memory5 state update */
    // Unit Delay state update: Memory5
    model->states.Memory5_state = model->signals.T_L_prime;

    /* Memory3 state update */
    // Unit Delay state update: Memory3
    model->states.Memory3_state = model->Saturn_Instrument_Unit_IU_LVDA_LVDC_LVDA_LVDC.outputs.bSIBStageSep;

    /* Memory1 state update */
    // Unit Delay state update: Memory1
    for (int i = 0; i < 3; i++) {
        model->states.Memory1_state[i] = model->signals.Saturn_Instrument_Unit_IU_Flight_Control_Computer_Mux5[i];
    }

    /* Memory2 state update */
    // Unit Delay state update: Memory2
    for (int i = 0; i < 3; i++) {
        model->states.Memory2_state[i] = model->signals.Saturn_Instrument_Unit_IU_Flight_Control_Computer_Mux6[i];
    }

    /* Memory4 state update */
    // Unit Delay state update: Memory4
    for (int i = 0; i < 3; i++) {
        model->states.Memory4_state[i] = model->signals.Saturn_Instrument_Unit_IU_Flight_Control_Computer_Sum1[i];
    }

    /* Memory6 state update */
    // Unit Delay state update: Memory6
    for (int i = 0; i < 3; i++) {
        model->states.Memory6_state[i] = model->signals.Saturn_Instrument_Unit_IU_Flight_Control_Computer_Product[i];
    }
    LVDA_LVDC_update_memory_states(&model->Saturn_Instrument_Unit_IU_LVDA_LVDC_LVDA_LVDC);
}

